mutating func save(
    products: [Product], using actions: ItemActions
) -> Result<UUID, ItemActions.ActionError> {
    if let savedItemID {
        return .success(savedItemID)
    }

    guard let product = selectedProduct(in: products) else {
        error = .productNotInContext
        return .failure(.productNotInContext)
    }

    let expiration = hasExpirationDate ? expirationDate : nil
    switch actions.create(for: product, expirationDate: expiration) {
    case .success(let item):
        savedItemID = item.id
        error = nil
        return .success(item.id)
    case .failure(let failure):
        error = failure
        return .failure(failure)
    }
}

final class Item {
    private(set) var id: UUID = UUID()
    @Relationship(deleteRule: .nullify, inverse: \Product.items)
    private(set) var product: Product?
    private(set) var expirationDate: Date?
    private(set) var statusRawValue: String = "unopened"
    private(set) var openingDate: Date?
    private(set) var consumedDate: Date?
    private(set) var updatedAt: Date = Date()

    /// 未知の保存値は保持し、未開封へ補完しない。
    var status: ItemStatus? {
        ItemStatus(rawValue: statusRawValue)
    }

    init(id: UUID = UUID(), product: Product, expirationDate: Date? = nil, updatedAt: Date = Date()) {
        self.id = id
        self.product = product
        self.expirationDate = expirationDate
        self.updatedAt = updatedAt

func create(
    for product: Product, expirationDate: Date? = nil, now: Date = Date()
) -> Result<Item, ActionError> {
    // rollbackはcontext全体に作用するため、今回以外の未保存変更があれば触らない。
    guard !context.hasChanges else {
        return .failure(.pendingChanges)
    }

    guard product.modelContext === context else {
        return .failure(.productNotInContext)
    }

    let item = Item(product: product, expirationDate: expirationDate, updatedAt: now)
    context.insert(item)

    switch save(context) {
    case .success:
        return .success(item)
    case .failure(let error):
        context.rollback()
        return .failure(.persistence(error))
    }
}

private func save() {
    guard _products.fetchError == nil else {
        return
    }

    switch state.save(products: products, using: ItemActions(context: modelContext)) {
    case .success:
        dismiss()
    case .failure:
        break
    }
}
